// The site posts { requestId, email, scope, from, to, lang } and nothing else.
const b = ($input.first().json.body) || {};
const keys = Object.keys(b).sort().join(',');
const iso = /^\d{4}-\d{2}-\d{2}$/;
const email = String(b.email || '').trim().toLowerCase();
const valid = keys === 'email,from,lang,requestId,scope,to'
  && /^[0-9a-f-]{36}$/i.test(String(b.requestId))
  && email.length <= 254
  && /^[^\s@<>"'(),;:]+@[^\s@<>"'(),;:]+\.[a-z]{2,}$/i.test(email)
  && ['marketing', 'cashflow', 'clients'].includes(b.scope)
  && iso.test(String(b.from)) && iso.test(String(b.to)) && b.from <= b.to
  && ['en', 'ru'].includes(b.lang);
if (!valid) return [{ json: { status: 'invalid' } }];

// Rolling 24 h limits, kept in the workflow's static data (production runs only):
// 3 emails per address, 40 in total. The address itself is not kept, only a short hash.
const s = $getWorkflowStaticData('global');
const now = Date.now();
s.sent = (s.sent || []).filter((e) => now - e.t < 86400000);
let h = 2166136261;
for (const c of email) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619) >>> 0; }
const key = h.toString(16);
if (s.sent.filter((e) => e.k === key).length >= 3 || s.sent.length >= 40) {
  return [{ json: { status: 'limited' } }];
}
s.sent.push({ k: key, t: now });
return [{ json: { status: 'ok', requestId: b.requestId, email, scope: b.scope, from: b.from, to: b.to, lang: b.lang } }];

// Builds the HTML email from the scope's rows and the LLM's three bullets. Every value is escaped.
const req = $('Check request and limits').first().json;
const pick = (name) => { try { return $(name).first().json.data; } catch (e) { return null; } };
const data = pick('Marketing data') || pick('Cash flow data') || pick('Clients data') || {};
let bullets = [];
try {
  const t = String($('Write commentary').first().json.text || '');
  bullets = t.split('\n').map((l) => l.replace(/^\s*[-*\u2022]\s*/, '').trim()).filter(Boolean).slice(0, 3);
} catch (e) { bullets = []; }

const ru = req.lang === 'ru';
const loc = ru ? 'ru-RU' : 'en-GB';
const L = ru ? {
  scope: { marketing: 'Маркетинг', cashflow: 'Денежный поток', clients: 'Клиенты' },
  stands: 'Главное', none: 'Нет данных за период.',
  byChannel: 'По каналам', byWeek: 'По неделям (последние 13)', byCategory: 'По статьям',
  byPlan: 'По тарифам', topBilled: 'Крупнейшие клиенты по выручке', topOverdue: 'Просроченная оплата',
  asOf: 'на', footer: 'Вымышленные данные: демо vosk.dev. Письмо отправлено, потому что его запросили в чате на vosk.dev. Если это были не вы, просто удалите его: адрес нигде не сохраняется.',
  h: { channel: 'Канал', spend: 'Расходы', impr: 'Показы', clicks: 'Клики', cpc: 'CPC', mqls: 'Лиды', cpl: 'Цена лида', t2p: 'Триал → оплата', newc: 'Новые', cac: 'CAC', week: 'Неделя', budget: 'Бюджет', target: 'План лидов', cat: 'Статья', amount: 'Сумма', share: 'Доля', ly: 'Год назад', cin: 'Приход', cout: 'Расход', net: 'Итого', close: 'Остаток', runway: 'Запас, мес.', overdue: 'Просрочено', ap14: 'К оплате 14 дн.', plan: 'Тариф', active: 'Активные', new4: 'Новые 4 нед.', churn4: 'Ушли 4 нед.', tenure: 'Срок, мес.', inv12: 'Счета 12 мес.', billed12: 'Выручка 12 мес.', name: 'Клиент', city: 'Город', since: 'С', inv: 'Счета', billed: 'Выручка всего' }
} : {
  scope: { marketing: 'Marketing', cashflow: 'Cash flow', clients: 'Clients' },
  stands: 'What stands out', none: 'No data for this period.',
  byChannel: 'By channel', byWeek: 'By week (last 13)', byCategory: 'By category',
  byPlan: 'By plan', topBilled: 'Top clients by billing', topOverdue: 'Overdue payers',
  asOf: 'as of', footer: 'Fictional data: a vosk.dev demo. You got this because it was requested in the data chat on vosk.dev. If that was not you, just delete it: the address is not stored.',
  h: { channel: 'Channel', spend: 'Spend', impr: 'Impressions', clicks: 'Clicks', cpc: 'CPC', mqls: 'Leads', cpl: 'Cost per lead', t2p: 'Trial to paid', newc: 'New', cac: 'CAC', week: 'Week', budget: 'Budget', target: 'Lead target', cat: 'Category', amount: 'Amount', share: 'Share', ly: 'Last year', cin: 'In', cout: 'Out', net: 'Net', close: 'Closing cash', runway: 'Runway, mo', overdue: 'Overdue', ap14: 'Payables 14 d', plan: 'Plan', active: 'Active', new4: 'New 4 wk', churn4: 'Churned 4 wk', tenure: 'Tenure, mo', inv12: 'Invoices 12 mo', billed12: 'Billed 12 mo', name: 'Client', city: 'City', since: 'Since', inv: 'Invoices', billed: 'Billed to date' }
};

const nf = (o) => new Intl.NumberFormat(loc, o);
const dash = (v) => v === null || v === undefined || v === '';
const eur = (v) => dash(v) ? '–' : nf({ style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(Number(v));
const eur2 = (v) => dash(v) ? '–' : nf({ style: 'currency', currency: 'EUR', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(v));
const num = (v) => dash(v) ? '–' : nf({ maximumFractionDigits: 1 }).format(Number(v));
const pct = (v) => dash(v) ? '–' : num(v) + ' %';
const day = (d) => dash(d) ? '–' : new Date(String(d).slice(0, 10) + 'T00:00:00Z').toLocaleDateString(loc, { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });
const txt = (v) => dash(v) ? '–' : String(v);
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

function table(cols, rows) {
  if (!Array.isArray(rows) || !rows.length) return '<p style="color:#6b7280;margin:6px 0 18px">' + esc(L.none) + '</p>';
  const cell = (c) => 'padding:6px 8px;text-align:' + (c.r ? 'right' : 'left') + ';';
  let t = '<table role="presentation" style="border-collapse:collapse;width:100%;font-size:13px;margin:6px 0 22px">';
  t += '<tr>' + cols.map((c) => '<th style="' + cell(c) + 'border-bottom:2px solid #0f172a;color:#334155;font-weight:600;white-space:nowrap">' + esc(c.h) + '</th>').join('') + '</tr>';
  rows.forEach((row, i) => {
    const code = String(row.channel_code || row.category_code || row.plan_code || '');
    const total = /^(total|total_in|total_out|net)$/.test(code);
    const bg = total ? 'background:#e2e8f0;font-weight:700;' : (i % 2 ? 'background:#f8fafc;' : '');
    t += '<tr style="' + bg + '">' + cols.map((c) => '<td style="' + cell(c) + 'border-bottom:1px solid #e2e8f0">' + esc(c.f(row[c.k])) + '</td>').join('') + '</tr>';
  });
  return t + '</table>';
}
const h2 = (s) => '<h2 style="font-size:15px;margin:18px 0 4px;color:#0f172a">' + esc(s) + '</h2>';
const H = L.h;
const last13 = (rows) => Array.isArray(rows) ? rows.slice(-13) : rows;

let body = '';
if (req.scope === 'marketing') {
  body += h2(L.byChannel) + table([
    { h: H.channel, k: 'channel_name', f: txt }, { h: H.spend, k: 'spend_eur', f: eur, r: 1 },
    { h: H.impr, k: 'impressions', f: num, r: 1 }, { h: H.clicks, k: 'clicks', f: num, r: 1 },
    { h: H.cpc, k: 'cpc_eur', f: eur2, r: 1 }, { h: H.mqls, k: 'mqls', f: num, r: 1 },
    { h: H.cpl, k: 'cost_per_mql_eur', f: eur, r: 1 }, { h: H.t2p, k: 'trial_to_paid_pct', f: pct, r: 1 },
    { h: H.newc, k: 'new_customers', f: num, r: 1 }, { h: H.cac, k: 'cac_eur', f: eur, r: 1 }
  ], data.byChannel);
  body += h2(L.byWeek) + table([
    { h: H.week, k: 'week_label', f: txt }, { h: H.spend, k: 'spend_eur', f: eur, r: 1 },
    { h: H.budget, k: 'budget_eur', f: eur, r: 1 }, { h: H.clicks, k: 'clicks', f: num, r: 1 },
    { h: H.cpc, k: 'cpc_eur', f: eur2, r: 1 }, { h: H.mqls, k: 'mqls', f: num, r: 1 },
    { h: H.target, k: 'mqls_target', f: num, r: 1 }, { h: H.newc, k: 'new_customers', f: num, r: 1 },
    { h: H.cac, k: 'cac_eur', f: eur, r: 1 }
  ], last13(data.byWeek));
} else if (req.scope === 'cashflow') {
  body += h2(L.byCategory) + table([
    { h: H.cat, k: 'category_name', f: txt }, { h: H.amount, k: 'amount_eur', f: eur, r: 1 },
    { h: H.share, k: 'share_pct', f: pct, r: 1 }, { h: H.ly, k: 'ly_amount_eur', f: eur, r: 1 }
  ], data.byCategory);
  body += h2(L.byWeek) + table([
    { h: H.week, k: 'week_label', f: txt }, { h: H.cin, k: 'cash_in_eur', f: eur, r: 1 },
    { h: H.cout, k: 'cash_out_eur', f: eur, r: 1 }, { h: H.net, k: 'net_eur', f: eur, r: 1 },
    { h: H.close, k: 'closing_cash_eur', f: eur, r: 1 }, { h: H.runway, k: 'runway_months', f: num, r: 1 },
    { h: H.overdue, k: 'overdue_receivables_eur', f: eur, r: 1 }, { h: H.ap14, k: 'payables_due_14d_eur', f: eur, r: 1 }
  ], last13(data.byWeek));
} else {
  const who = [
    { h: H.name, k: 'name', f: txt }, { h: H.city, k: 'city', f: txt }, { h: H.plan, k: 'plan_name', f: txt },
    { h: H.since, k: 'signup_date', f: day }, { h: H.tenure, k: 'tenure_months', f: num, r: 1 },
    { h: H.inv, k: 'invoices', f: num, r: 1 }, { h: H.billed, k: 'billed_to_date_eur', f: eur, r: 1 },
    { h: H.overdue, k: 'overdue_eur', f: eur, r: 1 }
  ];
  body += h2(L.byPlan) + table([
    { h: H.plan, k: 'plan_name', f: txt }, { h: H.active, k: 'active_customers', f: num, r: 1 },
    { h: H.new4, k: 'new_last_4w', f: num, r: 1 }, { h: H.churn4, k: 'churned_last_4w', f: num, r: 1 },
    { h: H.tenure, k: 'avg_tenure_months', f: num, r: 1 }, { h: H.inv12, k: 'invoices_last_12m', f: num, r: 1 },
    { h: H.billed12, k: 'billed_last_12m_eur', f: eur, r: 1 }, { h: H.overdue, k: 'overdue_eur', f: eur, r: 1 }
  ], data.byPlan);
  body += h2(L.topBilled) + table(who, data.topBilled);
  body += h2(L.topOverdue) + table(who, data.topOverdue);
}

const asOf = data.meta && data.meta.data_as_of ? String(data.meta.data_as_of).slice(0, 10) : req.to;
const to = req.to < asOf ? req.to : asOf;
const period = req.scope === 'clients' ? L.asOf + ' ' + day(to) : day(req.from) + ' – ' + day(to);
const title = 'Tidewell · ' + L.scope[req.scope];
const notes = bullets.length
  ? '<div style="background:#f1f5f9;border-left:4px solid #0ea5e9;padding:10px 14px;margin:16px 0 8px"><div style="font-weight:700;margin-bottom:4px">' + esc(L.stands) + '</div><ul style="margin:0;padding-left:18px">' + bullets.map((b) => '<li style="margin:3px 0">' + esc(b) + '</li>').join('') + '</ul></div>'
  : '';
const html = '<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif;color:#0f172a;max-width:760px;margin:0 auto">'
  + '<div style="background:#0f172a;color:#fff;padding:16px 20px;border-radius:8px 8px 0 0"><div style="font-size:19px;font-weight:700">' + esc(title) + '</div><div style="font-size:13px;opacity:.8;margin-top:2px">' + esc(period) + '</div></div>'
  + '<div style="padding:4px 20px 12px;border:1px solid #e2e8f0;border-top:0;border-radius:0 0 8px 8px">' + notes + body
  + '<p style="font-size:11px;color:#64748b;margin-top:18px">' + esc(L.footer) + '</p></div></div>';

return [{ json: { email: req.email, subject: title + ' · ' + period, html } }];
